create table xxcus.xxcmp_cases (
    case_id                      number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment
    by 1 cache 20 noorder nocycle nokeep noscale not null enable,
    case_number                  varchar2(30 byte) not null enable,
    request_id                   number not null enable,
    party_id                     number not null enable,
    parent_case_id               number,
    case_status                  varchar2(30 byte) default 'INVESTIGATION' not null enable,
    assigned_to                  varchar2(255 byte),
    risk_tier                    varchar2(30 byte),
    enhanced_kyc_flag            varchar2(1 byte) default 'N' not null enable,
    pep_flag                     varchar2(1 byte) default 'N' not null enable,
    sla_due_date                 date,
    investigation_completed_date timestamp(6),
    current_level                number,
    decision                     varchar2(30 byte),
    decision_date                timestamp(6),
    conditions                   varchar2(4000 byte),
    next_review_date             date,
    next_review_reason           varchar2(1000 byte),
    sar_required_flag            varchar2(1 byte),
    sar_notes                    varchar2(4000 byte),
    closed_date                  timestamp(6),
    workflow_id                  number,
    created_by                   varchar2(255 byte) not null enable,
    creation_date                timestamp(6) not null enable,
    last_updated_by              varchar2(255 byte) not null enable,
    last_update_date             timestamp(6) not null enable,
    last_update_login            varchar2(255 byte),
    object_version_number        number default 1 not null enable
);

alter table xxcus.xxcmp_cases
    add constraint xxcmp_cases_ck1
        check ( case_status in ( 'INVESTIGATION', 'PENDING_APPROVAL', 'APPROVED', 'REJECTED', 'CANCELLED' ) ) enable;

alter table xxcus.xxcmp_cases
    add constraint xxcmp_cases_ck2
        check ( enhanced_kyc_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_cases
    add constraint xxcmp_cases_ck3
        check ( pep_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_cases
    add constraint xxcmp_cases_ck4
        check ( decision in ( 'APPROVED', 'REJECTED' ) ) enable;

alter table xxcus.xxcmp_cases
    add constraint xxcmp_cases_ck5
        check ( sar_required_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_cases
    add constraint xxcmp_cases_pk primary key ( case_id )
        using index enable;

alter table xxcus.xxcmp_cases add constraint xxcmp_cases_uk1 unique ( case_number )
    using index enable;


